import html,json,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1]; run=Path(sys.argv[1]).resolve(); rel=run.relative_to(root).as_posix()
r=json.loads((run/'results.json').read_text()); a=json.loads((run/'alerts.json').read_text()); security=json.loads((run/'runtime-checks.json').read_text())
slides=[('CYBERTHREAT','CyberThreat','AI-assisted Detection · Détecter, analyser, expliquer.','Deux conteneurs, un réseau interne, des preuves réelles et une interface MCP OpenCode.'),('ARCHITECTURE','Architecture du laboratoire','Station → cible → preuves → analyste','512 Mo de RAM maximale pour les conteneurs. Aucun port publié. Systèmes de fichiers en lecture seule. Le noyau est partagé avec WSL2 : isolation distincte d’une VM.'),('RECONNAISSANCE','Reconnaissance TCP','101 ports testés · Nmap + Netcat','Port 8080 : service HTTP. Les autres ports du périmètre sont fermés. Un scan est un signal, pas une preuve de compromission.'),('CAPTURE','Collecte et corrélation','PCAP → TShark → trames et indicateurs','Deux PCAP complets, extraits SYN/HTTP, événements applicatifs et captures Wireshark. La station observe son propre trafic vers la cible.'),('SCÉNARIOS','Trois scénarios contrôlés','Scan · rafale de connexion · injection SQL','Données fictives uniquement. Les contrôles de référence vérifient le fonctionnement normal du service avant et après protection.'),('MITIGATION','Mesurer les protections','SQL paramétré + limitation à trois échecs','Avant : la tautologie expose deux noms. Après : aucun résultat. Les codes 401 deviennent 429 après trois échecs; cela bloque aussi temporairement une connexion correcte.'),('EXTENSION IA / MCP','Intégration MCP','OpenCode ↔ MCP ↔ Docker','Cinq outils bornés. Triage statique : SHA-256, type, entropie, chaînes, YARA. Aucune exécution du fichier. Les chaînes extraites ne sont jamais des instructions de confiance.'),('SÉCURITÉ','Des contrôles testés','Seccomp · capacités · montages · réseau','Accès à l’hôte refusé par filtrage du bridge. Connexion sortante refusée. Triage UID 65534, capacités effectives nulles. Une absence absolue d’évasion n’est pas garantie sur un noyau partagé.'),('VALIDATION','Résultats de validation','Résultats · PCAP · contrôles · intégrité','Tous les contrôles du scénario sont PASS. Le test MCP stdio et la connexion native OpenCode sont distincts. Les résultats sont associés aux artefacts de référence.'),('DÉMONSTRATION','Ouvrir les preuves réelles',run.name,'Utiliser les flèches pour naviguer. Ouvrir le dashboard pour comparer les phases et expliquer les limites de la détection.')]
style='''body{margin:0;background:#080f1b;color:#eff5fa;font:20px system-ui}section{min-height:100vh;padding:9vh 9vw;display:none;box-sizing:border-box}section.active{display:flex;flex-direction:column;justify-content:center}.eyebrow{color:#76edc3;letter-spacing:4px;font-size:14px}h1{font-size:clamp(45px,7vw,90px);line-height:1.02;max-width:1050px;letter-spacing:-3px;margin:30px 0}h2{font-size:28px;color:#ffc879;font-weight:500}p{color:#a7b7c9;line-height:1.6;max-width:950px}nav{position:fixed;bottom:20px;right:30px;display:flex;gap:12px;align-items:center}button,a{color:#76edc3;background:#172336;border:1px solid #33465b;border-radius:8px;padding:10px 18px;cursor:pointer;text-decoration:none}a{display:inline-block;width:max-content;margin-top:15px}small{position:fixed;bottom:26px;left:30px;color:#a7b7c9}'''
body=''
for i,(tag,title,sub,desc) in enumerate(slides):
 body+=f'<section class="{"active" if i==0 else ""}"><div class="eyebrow">{html.escape(tag)}</div><h1>{html.escape(title)}</h1><h2>{html.escape(sub)}</h2><p>{html.escape(desc)}</p>'
 if i==len(slides)-1: body+=f'<a href="{rel}/dashboard.html">Ouvrir le tableau de preuves ↗</a>'
 body+='</section>'
(root/'presentation.html').write_text('<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Présentation</title><style>'+style+'</style>'+body+'''<small>CYBERTHREAT</small><nav><button onclick="move(-1)">←</button><span id="count">1 / 10</span><button onclick="move(1)">→</button></nav><script>let index=0;const slides=[...document.querySelectorAll('section')];function move(n){slides[index].classList.remove('active');index=(index+n+slides.length)%slides.length;slides[index].classList.add('active');document.getElementById('count').textContent=(index+1)+' / '+slides.length}document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' ')move(1);if(e.key==='ArrowLeft')move(-1)})</script></html>''')
links=[('Rapport PDF','docs/reports/CyberThreat-Technical-Report.pdf'),('Tableau de preuves',rel+'/dashboard.html'),('Vue technique','presentation.html'),('Rapport technique','docs/FINAL-REPORT.md'),('Rapport sécurité','docs/SECURITY-VALIDATION.md'),('Workflow de validation','docs/VALIDATION-WORKFLOW.md'),('OpenCode + MCP','docs/AI-MCP.md'),('Runbook','docs/RUNBOOK.md'),('Dossier de preuves',rel+'/SHA256SUMS')]
body='<section class="active"><div class="eyebrow">NETWORK DETECTION & ANALYSIS</div><h1>CyberThreat</h1><p>Investigation réseau, protections comparées et triage statique assisté par MCP. Consulter les observations, les rapports et les contrôles du laboratoire.</p><div>'
for name,path in links: body+=f'<a style="margin:8px" href="{path}">{name} ↗</a>'
body+='</div><p style="font-size:14px">Exécution '+run.name+' · '+str(len(a))+' alertes · '+str(sum(r['checks'].values()))+' contrôles du scénario PASS. Voir le rapport de sécurité pour les tests et leurs limites.</p></section>'
(root/'START-HERE.html').write_text('<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CyberThreat : dossier technique</title><style>'+style+'</style>'+body+'</html>')
print('START-HERE.html and presentation.html generated from verified evidence')
